from scipy import stats

def evaluate_ab_test(control_group, treatment_group, alpha=0.05):
    t_stat, p_val = stats.ttest_ind(control_group, treatment_group)
    significant = p_val < alpha
    return {'t_statistic': t_stat, 'p_value': p_val, 'statistically_significant': significant}
